--- from: Assets/BundleResources/Prefabs/MoviePreview.prefab > name: MoviePreview
---@class MoviePreviewDialog
---@field Env                           	MoviePreviewDialog                      
---@field controller                    	Engine.UI.UILuaDialog                   
---@field RawImage                      	UnityEngine.RectTransform               
local MoviePreviewDialog = Class("MoviePreviewDialog")

function MoviePreviewDialog:__init()
    ---@type CriWare.CriManaMovieControllerForUI
    self.moviePlayer = nil
    self.moviePath = nil
end

function MoviePreviewDialog:__delete()
    self.moviePlayer = nil
    self.moviePath = nil
    self.controller = nil
end

function MoviePreviewDialog:Awake()
    self.moviePlayer = KTool.GetComponent(self.RawImage.gameObject, typeof(CriManaMovieControllerForUI))
    local parameters = self.controller.Argument.parameters
    if parameters then
        local moviePath = parameters.moviePath
        self.moviePath = moviePath
        if parameters.width and parameters.height then
            ---@type Engine.UI.UIAutoCameraFix
            local autoCameraFix = KTool.GetComponent(self.RawImage.gameObject, typeof(UIAutoCameraFix))
            if autoCameraFix then
                autoCameraFix.designW = checkNumber(parameters.width)
                autoCameraFix.designH = checkNumber(parameters.height)
            end
            ---@type UnityEngine.RectTransform
            local rectTrans = KTool.GetComponent(self.RawImage.gameObject, typeof(RectTransform))
            rectTrans.sizeDelta = Vector2.New(checkNumber(parameters.width), checkNumber(parameters.height))
        end
    end
    local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
    CriWareUtils.StopAll()
end


function MoviePreviewDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.moviePlayer.player.statusChangeCallback = function(status)
            if status == CS.CriWare.CriMana.Player.Status.Ready then
            elseif status == CS.CriWare.CriMana.Player.Status.PlayEnd then
                UIModule.BackDialog()
            end
        end
        self.moviePlayer.player:SetFile(nil, GameUtils.GetManaPath(self.moviePath))
        self.moviePlayer:Play()
    end))
    return coWait
end

function MoviePreviewDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.Broadcast("MoviePlayOver")
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.PlayLastBGMMusic()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return MoviePreviewDialog